$ErrorActionPreference = "Stop"

$ProjectRoot = (Get-Location).Path
$PackagePath = Join-Path $ProjectRoot "package.json"
$BatchPath = Join-Path $ProjectRoot "scripts\entity\batch-cached-emet-explanations.js"
$SchedulerPath = Join-Path $ProjectRoot "scripts\entity\schedule-cached-emet-generation.js"
$EnvPath = Join-Path $ProjectRoot ".env.local"
$P03Path = Join-Path $ProjectRoot ".private\entity\build\P03\evidence-packets.json"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".private\entity\backups\P04-batch-queue-fix-$Timestamp"

$BatchPayload = ""
$SchedulerPayload = ""

function Write-Payload {
    param([Parameter(Mandatory)][string]$Payload, [Parameter(Mandatory)][string]$Path)
    $directory = Split-Path -Parent $Path
    New-Item -ItemType Directory -Force -Path $directory | Out-Null
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Payload))
}

function Backup-File {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path $Path)) { return }
    $relative = $Path.Substring($ProjectRoot.Length).TrimStart('\', '/')
    $destination = Join-Path $BackupRoot $relative
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
    Copy-Item -Force $Path $destination
}

function Restore-Backup {
    if (-not (Test-Path $BackupRoot)) { return }
    Get-ChildItem -Path $BackupRoot -File -Recurse | ForEach-Object {
        $relative = $_.FullName.Substring($BackupRoot.Length).TrimStart('\', '/')
        $destination = Join-Path $ProjectRoot $relative
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
        Copy-Item -Force $_.FullName $destination
    }
}

function Set-EnvSetting {
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Value
    )

    if (-not (Test-Path $EnvPath)) {
        [System.IO.File]::WriteAllText(
            $EnvPath,
            "",
            (New-Object System.Text.UTF8Encoding($false))
        )
    }

    $content = Get-Content $EnvPath -Raw
    if ($null -eq $content) { $content = "" }
    $escaped = [regex]::Escape($Name)
    $pattern = "(?m)^\s*$escaped\s*=.*$"
    $replacement = "$Name=$Value"

    if ($content -match $pattern) {
        $updated = [regex]::Replace($content, $pattern, $replacement)
    }
    else {
        $updated = $content.TrimEnd() + "`r`n$replacement`r`n"
    }

    [System.IO.File]::WriteAllText(
        $EnvPath,
        $updated,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

if (-not (Test-Path $PackagePath)) {
    throw "package.json was not found. Run this installer from the ai-bible-app project root."
}
if (-not (Test-Path $P03Path)) {
    throw "P03 evidence-packets.json was not found."
}
if (-not (Test-Path $BatchPath)) {
    throw "The P04 Batch compiler was not found. Install P04 v1.3 first."
}
if (-not (Test-Path $SchedulerPath)) {
    throw "The P04 scheduler was not found. Install P04 v1.3 first."
}

New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null
foreach ($path in @($PackagePath, $BatchPath, $SchedulerPath, $EnvPath)) {
    Backup-File $path
}

try {
    Write-Host "Installing P04 Batch queue correction v1.4.0..." -ForegroundColor Cyan

    Write-Payload $BatchPayload $BatchPath
    Write-Payload $SchedulerPayload $SchedulerPath

    # Official GPT-5.6 Luna Tier-1 Batch queue limit: 5M enqueued prompt tokens.
    # Keep a 500k safety reserve. Output tokens are not part of the Batch queue cap.
    Set-EnvSetting "EMET_P04_BATCH_QUEUE_LIMIT" "5000000"
    Set-EnvSetting "EMET_P04_SCHEDULER_INPUT_TOKEN_BUDGET" "4500000"
    Set-EnvSetting "EMET_P04_SCHEDULER_COOLDOWN_HOURS" "0"
    Set-EnvSetting "EMET_P04_SCHEDULER_REQUEST_SIZE" "1"
    Set-EnvSetting "EMET_P04_OUTPUT_TOKEN_RESERVE" "600"

    # Update the deprecated v1.3 names as well so old commands cannot reapply
    # the incorrect 2M/1.6M daily interpretation.
    Set-EnvSetting "EMET_P04_TIER_DAILY_TOKEN_LIMIT" "5000000"
    Set-EnvSetting "EMET_P04_SCHEDULER_TOKEN_BUDGET" "4500000"

    $package = Get-Content $PackagePath -Raw | ConvertFrom-Json
    if (-not $package.scripts) {
        $package | Add-Member -MemberType NoteProperty -Name scripts -Value ([pscustomobject]@{})
    }
    $scripts = [ordered]@{}
    foreach ($property in $package.scripts.PSObject.Properties) {
        $scripts[$property.Name] = $property.Value
    }
    $scripts["emet:generate"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --run"
    $scripts["emet:generate:plan"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --plan"
    $scripts["emet:generate:status"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --status"
    $scripts["emet:generate:watch"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --run --watch"
    $package.scripts = [pscustomobject]$scripts

    [System.IO.File]::WriteAllText(
        $PackagePath,
        ($package | ConvertTo-Json -Depth 100) + "`r`n",
        (New-Object System.Text.UTF8Encoding($false))
    )

    & node --check $BatchPath
    if ($LASTEXITCODE -ne 0) { throw "P04 Batch compiler syntax validation failed." }

    & node --check $SchedulerPath
    if ($LASTEXITCODE -ne 0) { throw "P04 scheduler syntax validation failed." }

    Write-Host "`nInspecting the corrected scheduler plan (no API request)..." -ForegroundColor Cyan
    & npm run emet:generate:plan
    if ($LASTEXITCODE -ne 0) { throw "Corrected scheduler plan failed." }

    Write-Host "`nP04 Batch queue correction installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupRoot"
    Write-Host ""
    Write-Host "The currently active Batch job was preserved." -ForegroundColor Green
    Write-Host "Fastest continuation command:" -ForegroundColor Cyan
    Write-Host "npm run emet:generate:watch" -ForegroundColor Yellow
    Write-Host ""
    Write-Host "Keep that PowerShell window open. If it closes, run the same command again."
}
catch {
    Write-Host "`nInstallation failed. Restoring the previous files..." -ForegroundColor Red
    Restore-Backup
    throw
}
